   lease=canonical_bundle_lease(binary.parents[2]);lease.__enter__()
   if binary.is_file() and sha(binary)==r['executable_sha256']:
    selected=dict(receipt=str(Path(r['frozen_compilation']).parent),ready=r,frozen=f,canonical=True);release=lambda:lease.__exit__(None,None,None)
   else:lease.__exit__(None,None,None)
 except (OSError,ValueError,KeyError):pass
 if selected:break
 for receipt in sorted((state/'receipts').glob('20261108-*'),reverse=True):
  if not (receipt/'ready.json').exists() or (receipt/'result.json').exists():continue
