  try:
   r=json.loads((receipt/'ready.json').read_text());f=json.loads((receipt/'frozen-compile.json').read_text());binary=Path(r['ready_executable'])
   if not f.get('complete') or any(f.get('exact_source_manifest',{}).get(p)!=v for p,v in sources.items()):continue
   handle=(receipt/'artifact.lock').open('a');fcntl.flock(handle,fcntl.LOCK_SH|fcntl.LOCK_NB)
   if not binary.is_file() or sha(binary)!=r['ready_executable_sha256']:handle.close();continue
  except (OSError,ValueError,KeyError):
   if handle:handle.close()
   continue
  selected=dict(receipt=str(receipt),ready=r,frozen=f,canonical=False);release=handle.close;break
 if selected:break
 time.sleep(.25)
if not selected:raise SystemExit('No completed production build contains the current clock policy')
(out/'completed-checks7-identity.json').write_text(json.dumps(selected,indent=2));print(json.dumps(dict(binary=str(binary),sha256=sha(binary),canonical=selected['canonical'])),flush=True);commands=[]
